<script setup lang="ts">
import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{useAuthStore}from'../stores/auth'
const form=reactive({username:'',password:''}),loading=ref(false),auth=useAuthStore(),router=useRouter()
async function submit(){loading.value=true;try{await auth.login(form.username,form.password);await router.push(auth.user?.must_change_password?'/change-password':auth.user?.role==='student'?'/student/courses':'/')}catch(e:any){ElMessage.error(e.response?.data?.detail||(e.request?'无法连接 API，请先在项目目录运行 start.cmd':'登录失败，请检查账号和密码'))}finally{loading.value=false}}
</script>
<template><main class="login-shell"><section class="login-brand"><span class="eyebrow">ZHIJIAO CAMPUS</span><h1>让课程知识<br/>成为可信的学习依据</h1><p>教师建设课程知识库，学生通过学号进入已授权课程。</p></section><el-card class="login-card" shadow="never"><h2>账号登录</h2><p class="muted">教师账号或学生学号均可登录</p><el-form label-position="top" @submit.prevent="submit"><el-form-item label="用户名 / 学号"><el-input v-model="form.username" size="large" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" size="large" type="password" show-password autocomplete="current-password" @keyup.enter="submit"/></el-form-item><el-button type="primary" size="large" :loading="loading" :disabled="!form.username||!form.password" @click="submit">登录</el-button></el-form></el-card></main></template>
